#include <iostream>

int main() {
    const int capacity = 8;
    int values[capacity] = {10, 20, 30, 40};
    int length = 4;

    // 输入 2 99，输出 10 20 99 30 40。
    int index = 0;
    int value = 0;
    std::cin >> index >> value;
    if (std::cin.fail()) {
        std::cout << "请输入两个整数：下标和新值。\n";
        return 1;
    }

    if (index < 0 || index > length || length == capacity) {
        std::cout << "插入失败：下标超出范围，或顺序表已满。\n";
        return 1;
    }

    // 从右往左腾出插入的位置。
    for (int i = length; i > index; --i) {
        values[i] = values[i - 1];
    }
    values[index] = value;
    ++length;

    for (int i = 0; i < length; ++i) {
        if (i > 0) {
            std::cout << ' ';
        }
        std::cout << values[i];
    }
    std::cout << '\n';
    return 0;
}
